window.docContents[214].resolve({"/Development-Server/#serve-headers":{"contents":"Header rules add response headers to requests whose path begins with a prefix.\nLater rules override earlier ones for the same header name.\n\n[[headers]]\npath = \"/assets\"\nset = { \"Cache-Control\" = \"no-cache\", \"X-Frame-Options\" = \"DENY\" }\n\n\n","context":"Writing Documentation in Lean with Verso\u0009Development Server\u0009Configuration File","header":"9.3.3. Custom Headers","id":"/Development-Server/#serve-headers"},"/Literate-Programming/#literate-extra-assets":{"contents":"Additional CSS or JavaScript files can be included.\nPaths are relative to the project root.\nCSS files are added as <link> tags and JS files as <script> tags in every page:\n\nextra_css = [\"custom/style.css\", \"custom/print.css\"]\nextra_js = [\"custom/analytics.js\"]\n\n\nThese files are copied into the output directory and linked after the default Verso styles, so custom CSS can override any built-in rules.\n\n","context":"Writing Documentation in Lean with Verso\u0009Literate Programming\u0009Configuration File Reference","header":"8.3.12. Extra CSS and JavaScript","id":"/Literate-Programming/#literate-extra-assets"}});